// Patches android/app/src/main/AndroidManifest.xml (generated by `npx cap add android`)
// with the permissions Trackia needs for the @capacitor/camera cover-image picker:
// camera capture + reading/writing images across API levels.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';

const manifestPath = 'android/app/src/main/AndroidManifest.xml';

if (!existsSync(manifestPath)) {
  console.error(`Manifest not found at ${manifestPath}. Run "npx cap add android" first.`);
  process.exit(1);
}

let xml = readFileSync(manifestPath, 'utf8');

const PERMISSIONS = [
  '<uses-permission android:name="android.permission.CAMERA" />',
  '<uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" android:maxSdkVersion="32" />',
  '<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="32" />',
  '<uses-permission android:name="android.permission.READ_MEDIA_IMAGES" />',
  '<uses-feature android:name="android.hardware.camera" android:required="false" />',
];

const missing = PERMISSIONS.filter((perm) => {
  const name = perm.match(/android:name="([^"]+)"/)[1];
  return !xml.includes(name);
});

if (missing.length) {
  const block = missing.map((p) => `    ${p}`).join('\n');
  xml = xml.replace(/(<manifest[^>]*>)/, `$1\n${block}`);
  writeFileSync(manifestPath, xml, 'utf8');
  console.log(`AndroidManifest.xml patched with ${missing.length} permission(s).`);
} else {
  console.log('AndroidManifest.xml already has the required permissions.');
}
